CREATE TABLE document (id UUID PRIMARY KEY DEFAULT uuid_v7(),owner_id UUID NOT NULL,resource_id UUID NOT NULL,kind VARCHAR(16) NOT NULL,current_revision_id UUID,created_at TIMESTAMPTZ NOT NULL DEFAULT current_timestamp,updated_at TIMESTAMPTZ NOT NULL DEFAULT current_timestamp,version BIGINT NOT NULL DEFAULT 0,CHECK(kind IN ('DOCUMENT','ARTICLE','NOTE')),FOREIGN KEY(resource_id) REFERENCES resource(id),UNIQUE(owner_id,resource_id));
CREATE TABLE document_revision (id UUID PRIMARY KEY DEFAULT uuid_v7(),document_id UUID NOT NULL,owner_id UUID NOT NULL,revision_number BIGINT NOT NULL,content TEXT NOT NULL,content_schema_version VARCHAR(64) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT current_timestamp,created_by UUID NOT NULL,FOREIGN KEY(document_id) REFERENCES document(id) ON DELETE CASCADE,UNIQUE(document_id,revision_number));
ALTER TABLE document ADD CONSTRAINT fk_document_current_revision FOREIGN KEY(current_revision_id) REFERENCES document_revision(id);
CREATE TABLE document_working_copy (id UUID PRIMARY KEY DEFAULT uuid_v7(),document_id UUID NOT NULL,owner_id UUID NOT NULL,content TEXT NOT NULL,content_schema_version VARCHAR(64) NOT NULL,base_revision_id UUID,updated_at TIMESTAMPTZ NOT NULL DEFAULT current_timestamp,version BIGINT NOT NULL DEFAULT 0,FOREIGN KEY(document_id) REFERENCES document(id) ON DELETE CASCADE,FOREIGN KEY(base_revision_id) REFERENCES document_revision(id),UNIQUE(document_id));
CREATE TABLE document_publication (id UUID PRIMARY KEY DEFAULT uuid_v7(),document_id UUID NOT NULL,revision_id UUID NOT NULL,slug VARCHAR(512),state VARCHAR(16) NOT NULL DEFAULT 'DRAFT',published_at TIMESTAMPTZ,CHECK(state IN ('DRAFT','PUBLISHED','UNPUBLISHED')),FOREIGN KEY(document_id) REFERENCES document(id) ON DELETE CASCADE,FOREIGN KEY(revision_id) REFERENCES document_revision(id),UNIQUE(document_id));
CREATE INDEX idx_document_revision_history ON document_revision(document_id,revision_number DESC);
